    pub fn mark_as_expanded(&mut self, num: u8, flag: bool) -> bool {
        match num {
            91 | 92 | 93 => {
                if flag {
                    self.state[num as usize >> 3] |= 1 << (num & 7)
                } else {
                    self.state[num as usize >> 3] &= !(1 << (num & 7))
                }
                true
            }
            _ => false,
        }
    }

